import {STATUS,composePostText,LANGUAGES,CITIES,initials,canonicalStatus,recommended} from './domain.mjs';
import {esc,icon,btn,date,number,directions,workLink,formLink} from './ui.mjs';
const badge=a=>`<span class="status ${STATUS[canonicalStatus(a.status)]?.tone||'neutral'}"><i></i>${STATUS[canonicalStatus(a.status)]?.label||'Заявка'}</span>`;
const brand=()=>`<a class="brand" href="/">снег<span>*</span><small>CREATOR DESK</small></a>`;
const navs=[['review','people','Отбор'],['posts','threads','Threads'],['settings','settings','Настройки']];
export function layout(s,demo){return `${demo?`<div class="demo-bar"><span>Демонстрация · вымышленные анкеты</span><button data-role-switch>${s.user.role==='candidate'?'Кабинет менеджера':'Открыть анкету'} ${icon('arrow')}</button></div>`:''}<header class="topbar">${brand()}${s.user.role!=='candidate'?`<nav class="desktop-nav" aria-label="Разделы">${navs.map(([id,ic,label])=>`<button class="${s.view===id?'active':''}" data-view="${id}">${label}${id==='review'&&s.stats.review?`<span>${s.stats.review}</span>`:''}</button>`).join('')}</nav><div class="topbar-end"><span class="workspace-name">СНЕГ* / Казахстан</span><button class="icon-button" data-refresh aria-label="Обновить">${icon('refresh')}</button><span class="initials">${esc(initials(s.user.name||'Вы'))}</span></div>`:'<span class="quiet">Набор креаторов · Казахстан</span>'}</header><main id="main" class="page"></main><footer class="footer"><span>СНЕГ* / creator desk</span><span>Threads → анкета → выбор менеджера</span></footer>${s.user.role!=='candidate'?`<nav class="mobile-nav" aria-label="Разделы">${navs.map(([id,ic,label])=>`<button data-view="${id}" class="${s.view===id?'active':''}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav>`:''}`;}
function connectionNote(s){const c=s.connections;return `<aside class="context-rail"><div class="rail-note dark"><span class="eyebrow">НАЧАЛО ВОРОНКИ</span>${icon('threads','large')}<h2>${c.threads?'Поток начинается<br>с Threads.':'Начнём<br>с Threads.'}</h2><p>${c.threads?'Подключён @'+esc(c.threadsUsername||'аккаунт')+'. Готовьте посты и выбирайте время публикации.':'Подключите аккаунт бренда. Посты будут приводить кандидатов прямо в анкету.'}</p>${btn(c.threads?'К публикациям':'Подключить Threads','data-view="posts"','cream','arrow')}</div><div class="rail-note"><span class="eyebrow">КАК РАБОТАЕТ ОТБОР</span><ol class="steps-mini"><li><b>01</b><span>Кандидат оставляет анкету</span></li><li><b>02</b><span>${c.aiConnected?'ИИ объясняет, с кого начать':'Правила расставляют приоритеты'}</span></li><li><b>03</b><span>Вы выбираете и связываетесь</span></li></ol><p class="fine">${c.aiConnected?'ИИ не заменяет просмотр работы и решение менеджера.':'ИИ пока не подключён. Это честно обозначенный отбор по анкете.'}</p>${!c.aiConnected?'<button class="text-button" data-view="settings">Подключить ИИ '+icon('arrow')+'</button>':''}</div></aside>`;}
export function queueView(s){const tabs=[['all_new','Новые заявки',s.stats.review],['recommended','Рекомендации',s.stats.recommended],['waiting','Уточнения',s.stats.clarification],['selected','Выбранные',s.stats.selected],['archive','История',null]];return `<section class="page-head queue-head"><div><span class="eyebrow">НАБОР / ${esc(s.campaign.name)}</span><h1>Отбор, без лишнего.</h1><p>Каждая новая анкета здесь. Подходящие кандидаты — первыми.</p></div><div class="head-counter"><span>${String(s.stats.review||0).padStart(2,'0')}</span><div>кандидатов <br>ждут вашего решения</div></div></section><div class="editorial-grid"><section class="queue"><div class="queue-tabs" role="tablist" aria-label="Очереди">${tabs.map(([key,label,n])=>`<button role="tab" aria-selected="${s.bucket===key}" data-bucket="${key}" class="${s.bucket===key?'active':''}">${label}${n!==null?`<span>${n||0}</span>`:''}</button>`).join('')}</div><div class="queue-tools"><label class="search">${icon('search')}<input type="search" data-search value="${esc(s.search)}" placeholder="Имя, город или номер анкеты" aria-label="Поиск кандидатов"></label><select data-direction aria-label="Формат сотрудничества" ${s.search.trim()?'disabled title="Поиск работает по всем форматам"':''}><option value="">Все форматы</option value="ugc" ${s.direction==='ugc'?'selected':''}>UGC</option><option value="reach" ${s.direction==='reach'?'selected':''}>Охваты</option></select></div><div class="queue-label"><span>${number(s.total)} ${s.search?'найдено по всей базе':s.bucket==='selected'?'выбранных':'в очереди'}</span><span>${s.connections.aiConnected?'Сначала рекомендации ИИ':'Сначала совпадения по анкете'}</span></div><div class="candidate-list">${s.rows.length?s.rows.map(candidateCard).join(''):`<div class="empty"><span class="empty-mark">↗</span><h2>${s.search?'Совпадений пока нет.':s.bucket==='recommended'?'Дадим новым лицам шанс.':'Здесь пока спокойно.'}</h2><p>${s.search?'Попробуйте другое имя или номер заявки.':s.bucket==='recommended'?'Загляните во все новые анкеты: там могут быть кандидаты, которым нужно одно уточнение.':'Когда появятся заявки, они будут здесь. Запустите пост в Threads, чтобы начать набор.'}</p>${btn(s.bucket==='recommended'?'Смотреть все новые':'К публикациям',s.bucket==='recommended'?'data-bucket="all_new"':'data-view="posts"','secondary','arrow')}</div>`}</div>${s.hasMore?btn('Показать ещё','data-more','secondary full','plus'):''}<div class="queue-foot"><span>Пропущенные анкеты сохраняются в истории.</span>${btn('Отправить подборку в Telegram','data-shortlist','text','arrow')}</div></section>${connectionNote(s)}</div>`;}
function candidateCard(a){const ai=a.evaluation?.ai,reason=ai?.summary||a.evaluation?.summary||'Нужен просмотр анкеты';return `<article class="candidate" data-candidate-id="${a.id}"><div class="candidate-top"><span class="candidate-number">${a.id}</span>${badge(a)}</div><div class="candidate-body"><div class="candidate-person"><span class="portrait">${esc(initials(a.name))}</span><div><button class="name-link" data-detail="${a.id}"><h2>${esc(a.name)}</h2></button><p>${esc(a.city)}<span>·</span>${LANGUAGES[a.language]}</p><div class="pills">${directions(a)}</div></div></div><div class="candidate-reason"><span class="eyebrow">${ai?'ПОЧЕМУ ИИ ВЫДЕЛИЛ':'ПО АНКЕТЕ'}</span><p>${esc(reason)}</p><span class="fine">${a.evaluation?.aiStatus==='pending'?'ИИ готовит резюме':a.portfolio.length?'Работа приложена · нужен ваш взгляд':'Нужен пример работы'}</span></div></div><div class="candidate-bottom"><div>${a.portfolio[0]?workLink(a.portfolio[0]):'<span class="fine">Пример пока не приложен</span>'}</div>${btn('Открыть анкету',`data-detail="${a.id}"`,'text','arrow')}</div></article>`;}
function threadsConnection(s){const c=s.connections;return `<aside class="threads-connect"><span class="eyebrow">АККАУНТ БРЕНДА</span><div class="connection-title">${icon('threads')}<h2>${c.threads?'@'+esc(c.threadsUsername||'аккаунт'):'Подключить Threads'}</h2></div><p>${c.threads?'Аккаунт подключён. Публикации отправляются через официальный API Meta.':'Подключите аккаунт один раз — дальше работайте с постами здесь.'}</p>${c.threads?`<span class="status olive"><i></i>Доступ подтверждён</span>${c.threadsExpiresAt?'<p class="fine">Доступ до '+date(c.threadsExpiresAt)+'</p>':''}${btn('Отключить','data-disconnect','text')}`:s.user.role!=='admin'?'<p class="fine">Подключение настраивает владелец пространства.</p>':`<div class="setup-step"><b>01</b><div><h3>Приложение Meta</h3><p>В Meta for Developers создайте приложение с Threads API. Выберите сценарий «Access the Threads API». Добавьте аккаунт бренда в роли Threads Tester и примите приглашение в настройках Threads.</p><a class="text-button" href="https://developers.facebook.com/apps/" target="_blank" rel="noopener">Открыть Meta ${icon('external')}</a></div></div><div class="setup-step"><b>02</b><div><h3>Адрес возврата</h3><p>Добавьте этот адрес в Valid OAuth Redirect URIs приложения Meta.</p><div class="copy-field"><code>${esc(c.callbackUrl||'Откройте рабочий кабинет в Telegram')}</code><button class="icon-button" data-copy="${esc(c.callbackUrl||'')}" aria-label="Копировать адрес">${icon('copy')}</button></div></div></div><form data-form="threads-app" class="stack"><label>Threads App ID<input name="appId" inputmode="numeric" autocomplete="off" required placeholder="Из настроек приложения Meta"></label><label>Threads App Secret<input type="password" name="appSecret" autocomplete="new-password" required placeholder="Сохраняется только на сервере"></label>${btn(c.threadsAppReady?'Обновить приложение':'Сохранить настройки','type="submit"','secondary full')}</form>${btn('Войти в Threads',`data-authorize ${!c.threadsAppReady?'disabled':''}`,'primary full','arrow')}<details class="token-alternative"><summary>Уже есть Threads Access Token?</summary><form data-form="threads-token" class="stack"><p class="fine">Нужен Threads User Token с threads_basic и threads_content_publish. Facebook/Instagram Token не подойдёт.</p><label>Threads Access Token<input type="password" name="token" autocomplete="new-password" required></label>${btn('Проверить и подключить','type="submit"','secondary full')}</form></details>`}${c.threadsError?'<p class="inline-error">'+esc(c.threadsError)+'</p>':''}</aside>`;}
export function postsView(s){const p=s.postDraft;return `<section class="page-head"><div><span class="eyebrow">THREADS / ПРИВЛЕЧЕНИЕ</span><h1>Посты приводят.<br>Вы выбираете.</h1><p>Текст, время и ссылка на анкету — в одном месте.</p></div><span class="status ${s.connections.threads?'olive':'neutral'}"><i></i>${s.connections.threads?'@'+esc(s.connections.threadsUsername||'Threads'):'Аккаунт не подключён'}</span></section><div class="threads-grid"><section><form class="post-editor" data-form="post"><div class="section-top"><span class="eyebrow">НОВАЯ ПУБЛИКАЦИЯ</span><button type="button" class="text-button" data-post-template>Взять текст набора ${icon('plus')}</button></div><label class="sr-only" for="post-text">Текст публикации</label><textarea id="post-text" name="text" maxlength="500" rows="8" placeholder="Расскажите, кого ищет ваш бренд…">${esc(p.text)}</textarea><div class="editor-meta"><label class="check-line"><input type="checkbox" name="includeForm" ${p.includeForm!==false?'checked':''}>Добавить ссылку на анкету</label><span data-post-count>${[...composePostText(p.text,formLink(s.botUsername),p.includeForm!==false)].length} / 500</span></div><div class="post-link-preview"><span>Кандидат перейдёт в Telegram и заполнит анкету</span>${icon('arrow')}</div><label class="schedule-label">Когда опубликовать<input type="datetime-local" name="scheduledAt" value="${esc(p.scheduledAt||'')}"></label><p class="fine">Время вашего устройства: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</p><div class="editor-actions">${btn('Сохранить черновик','type="submit" name="intent" value="draft"','secondary')}${btn('Запланировать',`type="submit" name="intent" value="scheduled" ${!s.connections.threads?'disabled':''}`,'primary','arrow')}</div><p class="fine">${s.connections.threads?'Пост выйдет в указанное время, пока сервер работает.':'Черновик можно подготовить сейчас. Расписание включится после подключения аккаунта.'}</p></form><section class="post-list"><div class="section-top"><h2>План публикаций</h2><span>${s.posts.length}</span></div>${s.posts.length?s.posts.map(postRow).join(''):'<div class="empty small"><p>Первая публикация начнётся с вашего текста.</p></div>'}</section></section>${threadsConnection(s)}</div>`;}
function postRow(p){const labels={draft:'Черновик',scheduled:'В расписании',publishing:'Публикуется',published:'Опубликован',failed:'Нужна проверка',needs_check:'Проверьте аккаунт'};return `<article class="post-row"><div class="post-meta"><span class="status ${p.status==='published'?'olive':'neutral'}"><i></i>${labels[p.status]||p.status}</span><span>${date(p.scheduledAt||p.createdAt)}</span></div><p>${esc(p.text)}</p>${p.error?'<p class="inline-error">'+esc(p.error)+'</p>':''}<div class="post-row-actions">${['draft','scheduled','failed'].includes(p.status)?btn('Редактировать',`data-edit-post="${p.id}"`,'text'):''}${['draft','failed'].includes(p.status)?btn('Опубликовать сейчас',`data-publish="${p.id}"`,'text','arrow'):''}${p.status==='scheduled'?btn('Снять с расписания',`data-cancel-post="${p.id}"`,'text'):''}${p.permalink?`<a class="text-button" href="${esc(p.permalink)}" target="_blank" rel="noopener">Открыть в Threads ${icon('external')}</a>`:''}</div></article>`;}
export function settingsView(s){const c=s.campaign,admin=s.user.role==='admin';return `<section class="page-head"><div><span class="eyebrow">ПРАВИЛА / ПОДКЛЮЧЕНИЯ</span><h1>Настроить один раз.</h1><p>Условия набора и помощник для первого отбора.</p></div></section><div class="settings-grid"><section class="settings-section"><span class="eyebrow">КАМПАНИЯ</span><h2>Что обещаем креатору</h2><form data-form="campaign" class="stack"><label>Название набора<input name="name" value="${esc(c.name)}" required ${!admin?'disabled':''}></label><label>Условия сотрудничества<textarea rows="5" name="brief" required ${!admin?'disabled':''}>${esc(c.brief)}</textarea></label><div class="two-fields"><label>Сколько креаторов выбираем<input type="number" min="1" max="100000" name="limit" value="${c.limit}" ${!admin?'disabled':''}></label><label>Ориентир просмотров для охватов<input type="number" min="0" name="minViews" value="${c.minViews??1000}" ${!admin?'disabled':''}></label></div><p class="fine">Для UGC количество подписчиков не участвует в отборе. Охваты оцениваются отдельно по просмотрам и аудитории.</p><label class="check-line"><input name="active" type="checkbox" ${c.active?'checked':''} ${!admin?'disabled':''}>Принимать новые анкеты</label><details><summary>Условия для рабочего набора</summary><div class="stack"><label>Оператор данных<input name="operator" value="${esc(c.operator||'')}" ${!admin?'disabled':''}></label><label>Ссылка на политику<input type="url" name="privacyUrl" value="${esc(c.privacyUrl||'')}" ${!admin?'disabled':''}></label><label class="check-line"><input name="productionApproved" type="checkbox" ${c.productionApproved?'checked':''} ${!admin?'disabled':''}>Условия и политика утверждены владельцем</label></div></details>${admin?btn('Сохранить условия','type="submit"','primary'):''}</form></section><section class="settings-section ai-panel"><span class="eyebrow">ИИ-ПОМОЩНИК</span><h2>Меньше анкет.<br>Больше ясности.</h2><p>ИИ составляет короткое резюме и объясняет приоритет. Работу смотрит и решение принимает менеджер.</p><div class="connection-state"><span class="status ${s.connections.aiConnected?'olive':'neutral'}"><i></i>${s.connections.aiConnected?'Подключён '+esc(s.connections.aiModel):'Пока работают только правила'}</span></div>${admin?`<form data-form="ai" class="stack"><label>Ключ Google AI Studio<input name="key" type="password" autocomplete="new-password" placeholder="Вставьте ключ здесь, не в чат" required></label><details><summary>Выбрать модель вручную</summary><label>Имя модели<input name="model" placeholder="По умолчанию — доступная модель Flash"></label></details><p class="fine">Бесплатная квота зависит от аккаунта и модели. Контакты, имя, адреса и ссылки на работы модели не передаются. Видео она не просматривает.</p>${btn('Проверить и подключить','type="submit"','primary full','arrow')}</form>${s.connections.aiConnected?btn('Оставить только правила','data-ai-disable','text'):''}`:'<p class="fine">Ключ модели добавляет владелец пространства.</p>'}<div class="quiet-note"><h3>Подборка вместо потока</h3><p>О новых анкетах приходит уведомление, не чаще одного раза в 15 минут. Общая подборка обновляется в том же сообщении. Все заявки доступны в очереди.</p></div></section></div>`;}
export function detailView(s){const a=s.detail;if(!a)return '';const ai=a.evaluation?.ai;return `<div class="drawer-backdrop" data-close-detail></div><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="candidate-title"><header class="drawer-top"><span>${a.id}</span><button class="icon-button" data-close-detail aria-label="Закрыть карточку">${icon('close')}</button></header><div class="drawer-scroll"><div class="drawer-heading"><span class="eyebrow">${esc(a.city)} / ${LANGUAGES[a.language]}</span><h2 id="candidate-title">${esc(a.name)}</h2><div class="pills">${directions(a)}${badge(a)}</div>${s.connections.demo?'<span class="fine">Контакт появится в рабочей анкете</span>':a.username?`<a class="contact-link" href="https://t.me/${esc(a.username)}" target="_blank" rel="noopener">@${esc(a.username)} ${icon('external')}</a>`:/^\d+$/.test(a.telegramId)?`<a class="contact-link" href="tg://user?id=${esc(a.telegramId)}">Открыть в Telegram ${icon('external')}</a><p class="fine">Если Telegram не открывает профиль без имени пользователя, запросите контакт уточнением через бота.</p>`:''}</div><section class="detail-section"><div class="section-top"><h3>Первый взгляд</h3><span class="pill">${ai?'ИИ':'По анкете'}</span></div><p class="summary">${esc(ai?.summary||a.evaluation?.summary)}</p><ul class="reason-list">${(ai?.reasons||a.evaluation?.reasons||[]).map(x=>`<li>${icon('check')}${esc(x)}</li>`).join('')}</ul><div class="unknowns"><span class="eyebrow">ЧТО ПРОВЕРИТЬ</span>${(ai?.unknowns||a.evaluation?.unknowns||[]).map(x=>'<p>'+esc(x)+'</p>').join('')}</div></section><section class="detail-section"><h3>Работы</h3>${a.portfolio.length?a.portfolio.map(workLink).join(''):'<p class="fine">Кандидат пока не приложил работу. Можно запросить один пример.</p>'}${a.profile?a.profile.includes('example.com')?'<button class="text-button" data-demo-work>Профиль · демо</button>':`<a class="text-button" href="${esc(a.profile)}" target="_blank" rel="noopener">Профиль ${icon('external')}</a>`:''}</section><section class="detail-section facts"><div><span>Опыт</span><strong>${({brand:'Снимал(а) для брендов',blog:'Снимает для своего блога',beginner:'Первые проекты'})[a.experience]}</strong></div><div><span>Готовность</span><strong>За ${a.availabilityDays} дней</strong></div>${a.directions.includes('reach')?`<div><span>Средние просмотры</span><strong>${a.views===null?'Не указаны':number(a.views)}</strong></div><div><span>Аудитория в Казахстане</span><strong>${a.audienceKz?'Заявлена':'Нужно уточнить'}</strong></div>`:''}</section>${a.note?'<section class="detail-section"><h3>От кандидата</h3><p>'+esc(a.note)+'</p></section>':''}${a.question?'<section class="detail-section"><h3>Уточнение</h3><p>'+esc(a.question)+'</p>'+(a.answer?'<blockquote>'+esc(a.answer)+'</blockquote>':'<span class="fine">Ждём ответ в Telegram</span>')+'</section>':''}<details class="detail-section"><summary>История решения</summary>${(a.history||[]).map(e=>'<div class="history-item"><span>'+date(e.at)+'</span><p>'+esc(e.text)+'</p></div>').join('')||'<p class="fine">Пока только анкета.</p>'}</details></div><footer class="decision-bar">${['review','reserve'].includes(a.status)?btn('Выбрать',`data-decision="approve" data-id="${a.id}"`,'primary','check'):''}${a.status==='review'||a.status==='clarification'?btn('Уточнить',`data-decision="clarify" data-id="${a.id}"`,'secondary'):''}${a.status==='review'||a.status==='clarification'?btn('Пропустить',`data-decision="reject" data-id="${a.id}"`,'quiet'):''}${a.status==='approved'?btn('Товар отправлен',`data-decision="mark_sent" data-id="${a.id}"`,'primary','check'):''}${['reserve','rejected'].includes(a.status)?btn('Вернуть в отбор',`data-decision="reopen" data-id="${a.id}"`,'secondary'):''}</footer></section>`;}
export function candidateView(s){const a=s.mine[0],d=s.draft,c=s.campaign;if(a)return `<section class="application-wrap"><span class="eyebrow">ВАША АНКЕТА / ${a.id}</span><h1>${a.status==='approved'?'Вы в подборке бренда.':a.status==='sent'?'Менеджер отметил отправку.':'Анкета на месте.'}</h1><p>Решение и сообщения придут в этот же Telegram-бот.</p><div class="application-status">${badge(a)}<p>${a.status==='clarification'?esc(a.question):a.status==='approved'?'Менеджер свяжется с вами, чтобы договориться о товаре.':'Повторно заполнять анкету не нужно.'}</p></div>${a.status==='clarification'?`<form data-form="answer" class="stack"><label>Ответ менеджеру<textarea name="answer" required rows="4"></textarea></label>${btn('Отправить ответ','type="submit"','primary','arrow')}</form>`:''}<div class="quiet-note">${esc(c.brief)}</div></section>`;return `<section class="application-wrap"><span class="eyebrow">СНЕГ* / КРЕАТОРАМ</span><h1>Хорошая история<br>начинается с вас.</h1><p>${esc(c.brief)}</p>${!c.ready||!c.active?'<div class="empty"><h2>Набор скоро откроется.</h2><p>Бренд готовит условия. Загляните чуть позже.</p></div>':`<form data-form="application" class="application-form"><div class="form-progress"><span class="${s.step===1?'active':''}">01 / О вас</span><span class="${s.step===2?'active':''}">02 / Работа</span></div>${s.step===1?`<div class="stack"><label>Как к вам обращаться<input name="name" autocomplete="given-name" value="${esc(d.name||'')}" required placeholder="Имя и фамилия"></label><div class="two-fields"><label>Город<select name="city">${CITIES.map(city=>`<option ${d.city===city?'selected':''}>${city}</option>`).join('')}</select></label><label>Язык роликов<select name="language">${Object.entries(LANGUAGES).map(([v,label])=>`<option value="${v}" ${d.language===v?'selected':''}>${label}</option>`).join('')}</select></label></div><fieldset><legend>Как хотите сотрудничать?</legend>${[['ugc','Снимать для бренда','Создаю видео. Большой блог не нужен.'],['reach','Публиковать у себя','Делюсь с аудиторией. Добавлю статистику.']].map(([v,label,desc])=>`<label class="direction-option"><input type="checkbox" name="directions" value="${v}" ${d.directions.includes(v)?'checked':''}><span><strong>${label}</strong><small>${desc}</small></span></label>`).join('')}</fieldset>${btn('Перейти к работе','type="submit" name="intent" value="next"','primary full','arrow')}</div>`:`<div class="stack"><label>Пример ролика<textarea name="portfolio" rows="2" placeholder="До трёх ссылок, каждая с новой строки">${esc(d.portfolio||'')}</textarea><small>Подойдёт Reels, TikTok или видео с открытым доступом.</small></label><label>Опыт<select name="experience"><option value="brand" ${d.experience==='brand'?'selected':''}>Снимал(а) для брендов</option><option value="blog" ${d.experience==='blog'?'selected':''}>Снимаю для своего блога</option><option value="beginner" ${d.experience==='beginner'?'selected':''}>Это один из первых проектов</option></select></label>${d.directions.includes('reach')?`<label>Ваш профиль<input type="url" name="profile" value="${esc(d.profile||'')}" required placeholder="https://..."></label><div class="two-fields"><label>Средние просмотры<input type="number" min="0" name="views" value="${esc(d.views||'')}"></label><label>Подписчики<input type="number" min="0" name="followers" value="${esc(d.followers||'')}"></label></div><label class="check-line"><input type="checkbox" name="audienceKz" ${d.audienceKz?'checked':''}>Основная аудитория — в Казахстане</label>`:''}<label>Когда сможете снять?<select name="availabilityDays">${[3,7,14,30].map(n=>`<option value="${n}" ${Number(d.availabilityDays)===n?'selected':''}>В течение ${n} дней после получения</option>`).join('')}</select></label><label class="check-line"><input type="checkbox" name="closeup" required>Готов(а) снимать применение крупным планом</label><label class="check-line"><input type="checkbox" name="adult" required>Мне исполнилось 18 лет</label><label class="check-line"><input type="checkbox" name="terms" required>Прочитал(а) условия сотрудничества выше</label><label class="check-line"><input type="checkbox" name="consent" required>Согласен(на) на обработку анкеты для отбора и связи${c.privacyUrl?' · <a href="'+esc(c.privacyUrl)+'" target="_blank" rel="noopener">Политика</a>':''}</label><div class="editor-actions">${btn('Назад','type="button" data-form-back','secondary')}${btn('Отправить анкету','type="submit" name="intent" value="send"','primary','arrow')}</div></div>`}<p class="form-error" role="alert"></p></form>`}</section>`;}
export function welcome(s){return `<header class="topbar">${brand()}<span class="quiet">Креаторы · Казахстан</span></header><main class="application-wrap"><span class="eyebrow">СНЕГ* / НАБОР КРЕАТОРОВ</span><h1>Хорошая история<br>начинается с вас.</h1><p>${esc(s.campaign?.brief||'Ищем креаторов для честных видео по бартеру. Большой блог для UGC не нужен.')}</p><a class="button primary" href="https://t.me/${esc(s.botUsername||'sneg_ugc_bot')}?start=c_sneg-october">Открыть анкету в Telegram ${icon('arrow')}</a><p class="fine">Telegram нужен, чтобы мы могли ответить на вашу анкету.</p></main>`;}
